package request

import (
	"context"
	"io"
	"net/http"
)

type payloadKey struct{}

// Payload carries an optional streaming body beside generated byte-slice shapes.
// Body carries streaming responses (e.g. GetObject).
// Stream carries streaming requests (e.g. PutObject, UploadPart).
// In-process callers retain the generated API's buffered behavior.
// The gateway owns and closes Body and Stream.
type Payload struct {
	Body     io.ReadCloser
	Stream   io.ReadCloser
	Trailers func() http.Header
}

func WithPayload(ctx context.Context, payload *Payload) context.Context {
	return context.WithValue(ctx, payloadKey{}, payload)
}

func ResponsePayload(ctx context.Context) *Payload {
	payload, _ := ctx.Value(payloadKey{}).(*Payload)
	return payload
}
